/* ------------------------------------------------------------------
 * Multi-rate lookup (M2). Static/header-only, mirroring the existing
 * pattern of this header (this file is included by exactly one TU
 * today, c_impl/src/aec.c, so no cross-TU duplication concern yet;
 * if a second TU ever includes this header, follow the same
 * static-const-per-TU pattern already used for the arrays above).
 * ------------------------------------------------------------------ */
typedef struct {
    int sample_rate;
    int n_bins;
    int fft_size;
    int block_size;
    int hop_size;
    int n_partitions;
    int filter_taps_size;
    int filter_length;
    const float* synth_window;
    int synth_window_len;
    const float* sg_nearend_enr_tr;
    const float* sg_nearend_enr_su;
    const float* sg_nearend_emr_tr;
    const float* sg_normal_enr_tr;
    const float* sg_normal_enr_su;
    const float* sg_normal_emr_tr;
    int sg_table_len;
    int sg_last_lf_band;
    int sg_first_hf_band;
    int sg_last_lf_smoothing_band;
    int sg_lf_clamp_bin;
    int sg_dne_lf_end;
    int sg_dne_lf_endpoint_bin;
    int sg_aud_lf_end_bin;
    int sg_aud_mf_end_bin;
    int sg_hf_lgb;
    int ree_hop_size;
    /* Found genuinely rate-varying by the cross-rate invariance
     * assertion (gen_aec_balanced_config_h.py RATE_VARYING_MACROS) --
     * moved here rather than left as a single "constant". */
    float sg_low_render_threshold;
    float sg_floor_power;
    float sg_low_render_limit;
    float sg_normal_render_limit;
    float ree_min_noise_floor_power;
    float ree_nl_norm_power;
    float ree_residual_noise_gate_power;
    float noise_floor_int16sq;
} Aec3BalancedRateDims;

