static inline const Aec3BalancedRateDims* aec3b_rate_cfg(int sample_rate) {
    int i;
    int n = (int)(sizeof(AEC3B_RATE_TABLE) / sizeof(AEC3B_RATE_TABLE[0]));
    for (i = 0; i < n; ++i) {
        if (AEC3B_RATE_TABLE[i].sample_rate == sample_rate) {
            return &AEC3B_RATE_TABLE[i];
        }
    }
    return (const Aec3BalancedRateDims*)0;
}

